function riftFrame(ms){const dt=riftLast?Math.min(.04,(ms-riftLast)/1000):0;riftLast=ms;const touch=new Set(riftTouches.values()),pressed=(...keys)=>keys.some(k=>riftKeys.has(k)||touch.has(k));rift.step(dt,{left:pressed('a','arrowleft','left'),right:pressed('d','arrowright','right'),up:pressed('w','arrowup','up'),down:pressed('s','arrowdown','down'),attack:pressed('j','attack')});riftDraw();riftPortrait();riftUI();requestAnimationFrame(riftFrame);}requestAnimationFrame(riftFrame);
